import type { BlogArticleFaq} from '../../../types/blog';
export const BODY: string = "\n<p>আপনার হাতে একটা ছবি আছে, আর ফরমটা 50KB-র বেশি কোনো ফাইল নিচ্ছে না৤ ধাপগুলো জানা থাকলে পুরো কাজটা দুই মিনিটে শেষ হয়৤</p>\n<p>এই গাইডে পুরো প্রক্রিয়াটা ধাপে ধাপে দেখানো হয়েছে৤ সঠিক সোর্স ফাইল তৈরি করা, কমপ্রেসরে চালানো, ফলাফল যাচাই করা, আর যেসব সাধারণ সমস্যা মানুষকে আটকে দেয় সেগুলো ঠিক করা—সবই এখানে আছে৤</p>\n<p>কোনো সফটওয়্যার ইনস্টল করতে হবে না৤ নিচের সবকিছু সাধারণ ব্রাউজারে চলে, ল্যাপটপে কিংবা ফোনে৤</p>\n<h2 id=\"before-you-start\">শুরু করার আগে: সঠিক সোর্স ফাইল তৈরি করুন</h2>\n<p>আপনার কাছে থাকা সবচেয়ে ভালো অরিজিনাল ছবি দিয়ে শুরু করুন৤ ক্যামেরা থেকে সরাসরি আসা ছবি অনেক ভালোভাবে কমপ্রেস হয়, আগে একবার ছোট করা কপির তুলনায়৤</p>\n<p>ছবিটা চ্যাট অ্যাপের মাধ্যমে এলে সেটা হয়তো আগেই কমপ্রেস করা হয়েছে৤ ফল খারাপ দেখালে প্রেরকের কাছে অরিজিনাল ফাইলটি চেয়ে নিন৤</p>\n<p>কমপ্রেস করার আগে পোর্টালের নিয়মগুলো দেখে নিন৤ সর্বোচ্চ ফাইলের আকার, প্রয়োজনীয় পিক্সেলের মাপ, আর কোন ফরম্যাট গ্রহণযোগ্য—এই তিনটি জেনে নিন৤</p>\n<p>এই তিনটি সংখ্যা লিখে রাখুন৤ অন্ধভাবে কমপ্রেস করে সময় নষ্ট হয়, কারণ নিখুঁত 50KB ফাইলও বাতিল হবে যদি পোর্টাল তার ফরম্যাট না নেয়৤</p>\n<h2 id=\"step-1-open-the-tool\">ধাপ ১: 50KB কমপ্রেসর খুলুন</h2>\n<p>ব্রাউজারে <a href=\"/bn/image-50kb-te-compress-korun\">50KB-তে ছবি কমপ্রেস করার টুল</a> খুলুন৤ পেজটি কমপ্রেসর লোড করে, আর আপনার ফাইল আপনার ডিভাইসেই থাকে৤</p>\n<p>অ্যাকাউন্ট খুলতে হবে না৤ কোনো সাইন-আপ নেই, আপলোডের লাইন নেই, তাই সঙ্গে সঙ্গে শুরু করা যায়৤</p>\n<p>ফোনে থাকলে আপনার নিয়মিত ব্রাউজারটাই ব্যবহার করুন৤ আপলোড বোতামে ট্যাপ করলেই ফটো গ্যালারি খুলে যায়৤</p>\n<p>পোর্টালের পেজটা অন্য ট্যাবে খোলা রাখুন৤ কাজ করার সময় তার নিয়মগুলো চোখের সামনে থাকা ভালো৤</p>\n<h2 id=\"step-2-upload\">ধাপ ২: ছবি আপলোড করুন</h2>\n<p>ছবিটা আপলোডের জায়গায় টেনে ছেড়ে দিন, অথবা বোতামে ট্যাপ করে ফাইল বেছে নিন৤ JPG, PNG, WebP আর HEIC ফাইল নেওয়া হয়, প্রতিটি সর্বোচ্চ 25MB পর্যন্ত৤</p>\n<p>পাসপোর্ট ছবির ক্ষেত্রে পুরো রেজোলিউশনের অরিজিনালটাই আপলোড করুন৤ ছোট করার কাজটা টুল করবে, আপনাকে আগেভাগে মাপ বদলাতে হবে না৤</p>\n<p>স্বাক্ষরের স্ক্যানের ক্ষেত্রে সবচেয়ে পরিষ্কার স্ক্যানটি আপলোড করুন৤ সাদা পটভূমির স্ক্যান অনেক ভালো কমপ্রেস হয়, কাগজের ছবি কোণ থেকে তোলার তুলনায়৤</p>\n<p>ফাইল 25MB-র বেশি হলে আগে মাপ কমিয়ে বা নতুন করে এক্সপোর্ট করে নিন৤ ছবির স্ক্রিনশট নেওয়া খারাপ উপায়, কারণ এতে নয়েজ যোগ হয়৤</p>\n<h2 id=\"step-3-let-it-search\">ধাপ ৩: টুলকে সেরা কোয়ালিটি খুঁজতে দিন</h2>\n<p>ছবি লোড হলে টুল বাইনারি কোয়ালিটি সার্চ চালায়৤ 50KB-র নিচে থাকা সর্বোচ্চ কোয়ালিটি না পাওয়া পর্যন্ত সে বিভিন্ন কোয়ালিটি স্তর পরীক্ষা করে৤</p>\n<p>কোয়ালিটির সংখ্যা আপনাকে নিজে বেছে নিতে হবে না৤ এই সার্চের উদ্দেশ্যই হলো যাতে আপনাকে আন্দাজ করতে না হয়৤</p>\n<p>ফলাফলে Under 50KB ব্যাজটি খুঁজুন৤ এই ব্যাজ মানে ফাইলটি সীমা পেরিয়ে গেছে এবং জমা দেওয়ার জন্য নিরাপদ৤</p>\n<p>টুল যদি জানায় লক্ষ্য মেলেনি, ঘাবড়াবেন না৤ নিচের সমাধানগুলো বেশিরভাগ ক্ষেত্রেই এই সমস্যা মিটিয়ে দেয়৤</p>\n<h2 id=\"step-4-preview\">ধাপ ৪: ডাউনলোডের আগে প্রিভিউ দেখুন</h2>\n<p>ডাউনলোড করার আগে কমপ্রেস করা ছবির প্রিভিউ সবসময় দেখুন৤ ফাইলের আকার ঠিক থাকলেও ছবিটা নষ্ট হয়ে যেতে পারে৤</p>\n<p>যেসব জায়গা গুরুত্বপূর্ণ সেখানে জুম করে দেখুন৤ প্রতিকৃতিতে চোখ আর মুখের আউটলাইন দেখুন৤ নথিতে সবচেয়ে ছোট লেখাটা দেখুন৤</p>\n<p>টুলে তুলনার ভিউ থাকলে ফলাফল অরিজিনালের পাশে রেখে মেলান৤ ছোটখাটো পার্থক্য স্বাভাবিক, কিন্তু পড়া না যাওয়া লেখা স্বাভাবিক নয়৤</p>\n<p>প্রিভিউ খারাপ দেখালে হাল ছাড়ার আগে অন্য ফরম্যাট চেষ্টা করুন৤ PNG থেকে JPG-তে বদলালেই অনেক সময় লক্ষ্য সঙ্গে সঙ্গে মিলে যায়৤</p>\n<h2 id=\"step-5-download\">ধাপ ৫: ডাউনলোড করে পরিষ্কার নাম দিন</h2>\n<p>কমপ্রেস করা ফাইল ডাউনলোড করে পরিষ্কার একটা নাম দিন৤ passport-photo-50kb.jpg-এর মতো নাম মাসখানেক পরেও বলে দেবে এটা আসলে কী৤</p>\n<p>অরিজিনাল ফাইলটাও রেখে দিন৤ পোর্টাল কমপ্রেস করা কপি বাতিল করলে সোর্স না খুঁজে আবার চেষ্টা করা যাবে৤</p>\n<p>ডিভাইসে ডাউনলোড করা ফাইলের আকার দেখে নিন৤ এটা 50KB-র একটু নিচে থাকা উচিত, সাধারণত 48KB থেকে 49.9KB-র মধ্যে৤</p>\n<p>এই ছোট ব্যবধান ইচ্ছাকৃত৤ পোর্টাল বাইটে মাপে, আর সীমার একটু নিচে থাকলে রাউন্ডিংয়ের পার্থক্য থেকে আপনি নিরাপদ থাকেন৤</p>\n<h2 id=\"fixing-a-missed-target\">লক্ষ্য না মিললে যা করবেন</h2>\n<p>লক্ষ্য না মিললে সাধারণত তিনটি কারণের একটা থাকে৤ ফরম্যাট ভুল, মাপ আটকে আছে, অথবা সোর্স ছবিতে অস্বাভাবিক বেশি বিস্তারিত আছে৤</p>\n<p>প্রথমে আউটপুট ফরম্যাট JPG করুন৤ PNG ফরম্যাটের ছবি অনেক সময় যতই ছোট করুন 50KB-তে পৌঁছাতেই পারে না৤</p>\n<p>দ্বিতীয়ত, মাপ কমানোর অনুমতি দিন৤ টুল পিক্সেলের আকার ধাপে ধাপে কমায়, আর সামান্য কমালেই অনেক সময় লক্ষ্য মিলে যায়৤</p>\n<p>তৃতীয়ত, ফাঁকা বা শোরগোলযুক্ত প্রান্ত কেটে ফেলুন৤ ব্যস্ত পটভূমির ছবি এমন জায়গায় কিলোবাইট নষ্ট করে যেদিকে কেউ তাকায় না৤</p>\n<p>তিনটি চেষ্টার পরেও না মিললে সোর্স ছবিটা বদলে দেখুন৤ অন্য আলোয় তোলা বা কম বিস্তারিত ছবি 50KB-তে অনেক সহজে পৌঁছায়৤</p>\n<h2 id=\"passport-photo-tips\">পাসপোর্ট আর আইডি ছবির টিপস</h2>\n<p>পাসপোর্ট পোর্টালগুলো ফাইলের আকারের পাশাপাশি অনেক সময় নির্দিষ্ট মাপও চায়৤ 600 বাই 600 পিক্সেল আর 50KB-র নিচে—এই জোড়াটা খুব সাধারণ৤</p>\n<p>এমন ছবি দিয়ে শুরু করুন যেটা প্রয়োজনীয় আকৃতির কাছাকাছি৤ চওড়া ল্যান্ডস্কেপ ছবি বর্গাকার করতে গেলে ছবির বেশিরভাগটাই ফেলে দিতে হয়৤</p>\n<p>সাদামাটা হালকা পটভূমি ব্যবহার করুন৤ ব্যস্ত পটভূমি এমন বিস্তারিত যোগ করে যা কিলোবাইট খায় আর মুখ থেকে মনোযোগ সরায়৤</p>\n<p>মুখের আকারের নিয়মটাও দেখে নিন৤ অনেক পোর্টাল চায় মুখ ফ্রেমের নির্দিষ্ট অংশ জুড়ে থাকুক, আর কমপ্রেশন ছোট মুখ ঠিক করতে পারে না৤</p>\n<p>ছবি তোলার সময় মাথা সোজা রাখুন আর কাঁধ পর্যন্ত ফ্রেমে রাখুন৤ এই ফ্রেমিং পরে ক্রপ করা সহজ করে আর 50KB-র বাজেট মুখের জন্যই খরচ হয়৤</p>\n<h2 id=\"signature-scan-tips\">স্বাক্ষর আর স্ক্যান করা নথির টিপস</h2>\n<p>স্বাক্ষর দারুণভাবে কমপ্রেস হয়, কারণ এর বেশিরভাগটাই সাদা জায়গা৤ পরিষ্কার স্ক্যান কোয়ালিটি বাঁচিয়ে সহজেই 50KB-তে পৌঁছে যায়৤</p>\n<p>যুক্তিসংগত রেজোলিউশনে স্ক্যান করুন৤ 300 DPI স্ক্যান যথেষ্ট, 1200 DPI স্ক্যান শুধু বিশাল ফাইল বানায় যেটা আরও কঠিনভাবে ছোট করতে হয়৤</p>\n<p>আপলোডের আগে স্ক্যান সোজা করে নিন৤ বাঁকা স্বাক্ষর ফাঁকা কোণে পিক্সেল নষ্ট করে, যা কোনো কাজে আসে না৤</p>\n<p>কমপ্রেসের পর স্বাক্ষর কালো না হয়ে ধূসর দেখালে আপলোডের আগে কনট্রাস্ট একটু বাড়ান৤ গাঢ় কালি হালকা পেনসিলের দাগের চেয়ে কমপ্রেশন ভালোভাবে সহ্য করে৤</p>\n<p>স্বাক্ষরের চারপাশে বেশি সাদা জায়গা থাকলে ক্রপ করুন৤ সাদা জায়গা কমপ্রেস হয় বটে, কিন্তু কম পিক্সেল মানে কালির জন্য আরও বাজেট৤</p>\n<h2 id=\"phone-workflow\">ফোনে পুরো কাজটা করা</h2>\n<p>ফরমের জন্য ছবি কমপ্রেস করা বেশিরভাগ মানুষই ফোনে করেন৤ কাজের ধারা একই, শুধু কয়েকটা ছোট পার্থক্য আছে৤</p>\n<p>গ্যালারি থেকে অরিজিনাল ছবিটা বেছে নিন, চ্যাট অ্যাপ থেকে সংরক্ষণ করা কপি নয়৤ চ্যাট অ্যাপ আপনার দেখার আগেই ছবি ছোট করে ফেলে৤</p>\n<p>আইফোনে ছবি HEIC ফাইল হতে পারে৤ টুল HEIC নেয়, তাই আগে কনভার্ট না করে সরাসরি আপলোড করুন৤</p>\n<p>ডাউনলোডের পর ফাইলস অ্যাপে ফাইলটি দেখে নিন৤ পোর্টালে ফেরার আগে নিশ্চিত হোন আকার 50KB-র নিচে আছে৤</p>\n<p>ফোনের ব্রাউজারে ডেস্কটপ সাইট চাইলে সেটিং থেকে ডেস্কটপ ভিউ চালু করা যায়৤ তবে সাধারণভাবে মোবাইল ভিউতেই 50KB টুল পুরোপুরি কাজ করে৤</p>\n<h2 id=\"checking-your-result\">ফলাফল ঠিকভাবে যাচাই করা</h2>\n<p>ডাউনলোড করা ফাইলটা পুরো আকারে খুলে দেখুন৤ থাম্বনেইলে এমন সমস্যা লুকিয়ে থাকে যা পোর্টালের পরীক্ষক দেখতে পাবেন৤</p>\n<p>ছবিতে থাকা যেকোনো লেখা জোরে জোরে পড়ুন৤ প্রতিটি শব্দ পড়া গেলে বুঝবেন কমপ্রেশন তার কাজ করেছে৤</p>\n<p>ফাইলটা পোর্টালে আপলোড করে তার নিজের নিশ্চিতকরণ দেখুন৤ কিছু পোর্টাল প্রিভিউ দেখায়, সেটা দিয়ে ছবি ঠিকভাবে দেখাচ্ছে কি না মিলিয়ে নিন৤</p>\n<p>পোর্টাল এখনও ফাইল বাতিল করলে সঠিক ত্রুটির বার্তাটা পড়ুন৤ হয়তো সমস্যা মাপ বা ফরম্যাটে, আকারে নয়, আর প্রতিটি সমস্যার সমাধান আলাদা৤</p>\n<p>যাচাইয়ের সময় ফাইলের আকার বাইটে দেখুন, শুধু গোল করা সংখ্যায় নয়৤ 49.9KB দেখালেও বাইটের হিসাব সীমা ছাড়িয়ে যেতে পারে৤</p>\n<h2 id=\"choosing-dimensions\">কমপ্রেসের আগে মাপ বেছে নেওয়া</h2>\n<p>মাপ আর ফাইলের আকার একে অপরের সঙ্গে জড়িত৤ ছোট ছবিতে কম তথ্য লাগে, তাই কম কোয়ালিটি নষ্ট করে 50KB-তে পৌঁছায়৤</p>\n<p>আপনার পোর্টাল মাপ ঠিক করে দিয়েছে কি না দেখুন৤ দিয়ে থাকলে সিদ্ধান্তটা আপনার নয়, আর তার বিরুদ্ধে যাওয়া উচিত নয়৤</p>\n<p>মাপ স্বাধীন হলে সবচেয়ে ছোট সেই আকারটি নিন যা দেখানোর আকারে ভালো দেখায়৤ 300 পিক্সেল চওড়ায় দেখানো ছবির 2000 পিক্সেল চওড়া হওয়ার দরকার নেই৤</p>\n<p>মাপ কমানো আপনার হাতে সবচেয়ে শক্তিশালী উপায়৤ প্রস্থ আর উচ্চতা অর্ধেক করলে পিক্সেলের সংখ্যা চার ভাগের এক ভাগ হয়ে যায়৤</p>\n<p>সম্ভব হলে মাপ বদলানোর কাজটা টুলের হাতে ছেড়ে দিন৤ ধাপে ধাপে মাপ কমানোর ব্যবস্থা প্রথমে পুরো আকার চেষ্টা করে, লক্ষ্য দাবি করলেই কেবল কমায়৤</p>\n<h2 id=\"scanned-documents\">স্ক্যান করা নথি 50KB-তে কমপ্রেস করা</h2>\n<p>স্ক্যান করা নথি ছবির চেয়ে আলাদাভাবে আচরণ করে৤ এগুলো বেশিরভাগই সাদা জায়গা আর গাঢ় লেখা, যা খুব দক্ষতার সঙ্গে কমপ্রেস হয়৤</p>\n<p>রঙ দরকার না হলে গ্রেস্কেলে স্ক্যান করুন৤ গ্রেস্কেল স্ক্যান রঙের তথ্যের এক-তৃতীয়াংশ বহন করে আর সহজেই 50KB-তে পৌঁছে যায়৤</p>\n<p>কমপ্রেসের আগে স্ক্যান পরিষ্কার করুন৤ ধুলোর দাগ আর ছায়া এমন নয়েজ যোগ করে যা কিছু না কিছুর জন্য কিলোবাইট নষ্ট করে৤</p>\n<p>কমপ্রেসের পর সবচেয়ে ছোট লেখাটা দেখুন৤ মূল লেখা সাধারণত টিকে যায়, কিন্তু ফুটনোট আর স্ট্যাম্প নরম হয়ে যেতে পারে৤</p>\n<p>স্ট্যাম্প বা সিল গুরুত্বপূর্ণ হলে মাপ উদার রাখুন৤ ছোট রঙিন বিবরণ চেনা যাওয়ার জন্য পিক্সেল দরকার৤</p>\n<h2 id=\"heic-photos\">আইফোনের HEIC ছবি নিয়ে কাজ করা</h2>\n<p>আইফোন ডিফল্টভাবে HEIC-তে ছবি সংরক্ষণ করে৤ এই ফাইলগুলো আগেই ভালোভাবে কমপ্রেস করা, যা 50KB-তে পৌঁছানো কঠিন করে তুলতে পারে৤</p>\n<p>HEIC ফাইল সরাসরি টুলে আপলোড করুন৤ টুল HEIC পড়ে আর কমপ্রেসের সময়ই কনভার্ট করে, তাই আলাদা কনভার্টের ধাপ লাগে না৤</p>\n<p>আগে অন্য অ্যাপে HEIC-কে JPG-তে বদলানো সাধারণত অপচয়৤ এতে আসল কমপ্রেশন শুরুর আগেই একটা ক্ষতিকর ধাপ যোগ হয়৤</p>\n<p>ফলাফল যত্ন করে দেখুন৤ HEIC ছবিতে প্রায়ই সমৃদ্ধ বিস্তারিত থাকে, আর 50KB-তে নামলে সূক্ষ্ম টেক্সচার প্রত্যাশার চেয়ে বেশি নরম হয়ে যেতে পারে৤</p>\n<p>ফল খারাপ দেখালে আবার চেষ্টার আগে ছবিটা আরও টাইট করে ক্রপ করুন৤ কাছের ক্রপে সীমিত বাজেটের বেশি অংশ মুখের জন্য থাকে৤</p>\n<h2 id=\"batch-50kb\">একসঙ্গে অনেক ফাইল 50KB-তে কমপ্রেস করা</h2>\n<p>অনেক ফরমে দুটি ফাইল লাগে: ছবি আর স্বাক্ষর৤ একসঙ্গে কমপ্রেস করলে সময় বাঁচে আর ফলাফল সামঞ্জস্যপূর্ণ থাকে৤</p>\n<p>দুটো ফাইল এক ব্যাচে টুলে যোগ করুন৤ প্রতিটি ফাইল আলাদাভাবে 50KB-র নিচে কমপ্রেস হয়৤</p>\n<p>ফলাফল ZIP ফাইলে ডাউনলোড করুন৤ আবেদনের নথি যেখানে রাখেন সেই ফোল্ডারে এটা এক্সট্রাক্ট করুন৤</p>\n<p>এক্সট্রাক্টের পর প্রতিটি ফাইল আলাদাভাবে দেখে নিন৤ স্বাক্ষর আর প্রতিকৃতির চাহিদা আলাদা, আর একটায় আবার চেষ্টা লাগতে পারে৤</p>\n<p>আপলোডের আগে এক্সট্রাক্ট করা ফাইলগুলোর পরিষ্কার নাম দিন৤ ছবি আর স্বাক্ষর গুলিয়ে ফেলা লজ্জাজনক আর এড়ানো যায় এমন ভুল৤</p>\n<h2 id=\"verifying-before-submit\">জমা দেওয়ার আগে শেষ যাচাই তালিকা</h2>\n<p>ডিভাইসে ফাইলের আকার 50KB-র নিচে আছে কি না নিশ্চিত করুন৤ 48KB থেকে 49.9KB-র মধ্যে একটা সংখ্যা খুঁজুন৤</p>\n<p>ফরম্যাট পোর্টালের নিয়মের সঙ্গে মিলছে কি না নিশ্চিত করুন৤ নিখুঁত WebP ফাইলও বাতিল হবে, যদি পোর্টাল শুধু JPG নেয়৤</p>\n<p>পোর্টাল মাপ ঠিক করে দিলে সেটাও নিশ্চিত করুন৤ ছবির প্রপার্টি খুলে পিক্সেলের সংখ্যা সরাসরি পড়ে নিন৤</p>\n<p>ছবিটা আরেকবার খুলে দেখুন৤ পুরো আকারে মুখ, লেখা আর প্রান্তগুলো দেখে নিন৤</p>\n<p>তারপরই পোর্টালে আপলোড করুন৤ এখন দুই মিনিটের যাচাই পরে আবেদন বাতিল হওয়ার চেয়ে ভালো৤</p>\n<h2 id=\"group-photos\">50KB-তে গ্রুপ ছবি আর ভিড়ের ছবি</h2>\n<p>গ্রুপ ছবি 50KB-তে সবচেয়ে কঠিন ক্ষেত্র৤ প্রতিটি মুখের বিস্তারিত দরকার, আর বিশটি মুখের জন্য একটি মুখের বিশ গুণ বিস্তারিত লাগে৤</p>\n<p>গ্রুপটাকে যতটা সম্ভব টাইট করে ক্রপ করুন৤ ফাঁকা আকাশ আর মাটি সরিয়ে দিন, যাতে মুখগুলো ফ্রেম ভরে ফেলে আর বাজেটের বেশি অংশ পায়৤</p>\n<p>মেনে নিন প্রতিটি মুখ নরম হয়ে যাবে৤ 50KB-তে গ্রুপ ছবি অনুষ্ঠানের রেকর্ড হিসেবে কাজ করে, প্রতিকৃতির সংগ্রহ হিসেবে নয়৤</p>\n<p>মুখগুলো চেনা যাওয়া জরুরি হলে বড় আকার ব্যবহার করুন৤ ফরম অনুমতি দিলে গ্রুপ ছবি 100KB বা 200KB-তেই রাখা উচিত৤</p>\n<p>ফরম 50KB-তেই অনড় থাকলে সামগ্রিক বিন্যাসকে অগ্রাধিকার দিন৤ এই আকারে কোনো একক মুখের চেয়ে পরিষ্কার গ্রুপ সাজানো বেশি গুরুত্বপূর্ণ৤</p>\n<h2 id=\"file-naming\">ফাইল এমনভাবে নাম দিন যাতে কখনো গুলিয়ে না যায়</h2>\n<p>কমপ্রেস করা ফাইলে টুল প্রায়ই সাধারণ নাম দেয়, আর সাধারণ নাম ভুলের কারণ হয়৤ image-50kb.jpg নামের ফাইল বলবে না এটা কার ছবি৤</p>\n<p>নাম দেওয়ার অভ্যাস গড়ুন: উদ্দেশ্য, ব্যক্তি, আর আকার৤ visa-photo-ahmed-50kb.jpg-এর মতো নাম মাসখানেক পরেও পরিষ্কার থাকে আর গুলিয়ে ফেলা অসম্ভব৤</p>\n<p>সব আবেদনে একই ধরন রাখুন৤ প্রতিটি ফাইল একই আকারে থাকলে সঠিকটা খুঁজে পেতে কয়েক সেকেন্ড লাগে৤</p>\n<p>কমপ্রেস করা ফাইল যে আবেদনের, তার সঙ্গেই রাখুন৤ ডাউনলোড ফোল্ডারে পড়ে থাকা ছবি হারিয়ে যাওয়ার অপেক্ষায় থাকে৤</p>\n<p>ডাউনলোডের পরপরই ফাইলের নাম বদলে ফেলুন, যখন উদ্দেশ্যটা মনে তাজা আছে৤ পরে আপনি মনে রাখতে পারবেন না কোন ছবি কোন ফরমের ছিল৤</p>\n<h2 id=\"portal-previews\">দ্বিতীয়বার যাচাই করতে পোর্টালের প্রিভিউ ব্যবহার করা</h2>\n<p>অনেক পোর্টাল আপলোডের পর প্রিভিউ দেখায়৤ এটা ব্যবহার করুন৤ প্রিভিউ হলো পোর্টালের নিজের চোখে আপনার ছবি, আর সমস্যা ধরার শেষ সুযোগ৤</p>\n<p>ছবিটা সোজা আছে কি না দেখুন৤ প্রিভিউতে উল্টো ছবি মানে পোর্টাল আপনার ফোনের চেয়ে ভিন্নভাবে অভিমুখ পড়েছে৤</p>\n<p>মুখ মাঝখানে আছে কি না আর পুরোটা দেখা যাচ্ছে কি না দেখুন৤ প্রান্ত কাটা প্রিভিউ থুতনি বা কপাল কেটে ফেলতে পারে৤</p>\n<p>ছবিটা টানা হয়েছে কি না দেখুন৤ কিছু পোর্টাল আপলোড করা ছবি নির্দিষ্ট ফ্রেমে জোর করে বসায়, আর প্রিভিউতে টানা মুখ সহজেই চোখে পড়ে৤</p>\n<p>কিছু ভুল দেখালে ফিরে গিয়ে সোর্স ফাইল ঠিক করুন৤ জমা দিয়ে আশা করবেন না যে পরীক্ষক এটা উপেক্ষা করবেন৤</p>\n<p>কেন 50KB সীমা থাকে আর কমপ্রেশন কীভাবে কাজ করে, তার পুরো পটভূমি জানতে পড়ুন <a href=\"/bn/blog/image-50kb-te-compress-korun-guide\">50KB-তে ছবি কমপ্রেস: সম্পূর্ণ গাইড</a>৤</p>\n<p>সিদ্ধান্ত নেওয়ার আগে আকারগুলো তুলনা করে দেখুন <a href=\"/bn/blog/image-size-50kb-vs-100kb-vs-200kb\">50KB বনাম 100KB বনাম 200KB: কোন সাইজ বেছে নেবেন?</a>৤ পোর্টাল বড় ফাইল নিলে <a href=\"/bn/image-100kb-te-compress-korun\">100KB কমপ্রেসর</a> লক্ষণীয়ভাবে বেশি বিস্তারিত ধরে রাখে৤</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ছবি 50KB-তে কমপ্রেস করতে কত সময় লাগে?","answer":"সাধারণত এক মিনিটের কম৤ বাইনারি কোয়ালিটি সার্চ সাধারণ ফোন বা ল্যাপটপে কয়েক সেকেন্ডে চলে, আর ধীর অংশ শুধু খুব বড় অরিজিনাল আপলোড করা৤ 10MB ছবি 2MB ছবির চেয়ে একটু বেশি সময় নিতে পারে৤"},{"question":"একসঙ্গে অনেক ছবি 50KB করা যায়?","answer":"হ্যাঁ, টুলে ব্যাচ প্রসেসিং আছে৤ একাধিক ছবি যোগ করুন, প্রতিটি 50KB-র নিচে কমপ্রেস হবে, তারপর ZIP হিসেবে একসঙ্গে ডাউনলোড করুন৤ ফরমে ছবি আর স্বাক্ষর দুটোই লাগলে এটা কাজে আসে৤"},{"question":"ডাউনলোড করা ফাইল ঠিক 50KB না হয়ে 48KB কেন?","answer":"টুল ইচ্ছা করে সীমার একটু নিচে লক্ষ্য করে, সাধারণত 48 থেকে 49.9KB-র মধ্যে৤ পোর্টাল বাইটে মাপে আর সিস্টেমভেদে রাউন্ডিং আলাদা হতে পারে, তাই এই ছোট নিরাপত্তা ব্যবধান আপনার ডিভাইসে পাস করা ফাইল পোর্টালে বাতিল হওয়া থেকে বাঁচায়৤"},{"question":"পোর্টাল 50KB-র নিচে আর 600 বাই 600 পিক্সেলের ছবি চায়৤ দুটো কীভাবে করব?","answer":"বর্গাকারের কাছাকাছি ছবি দিয়ে শুরু করুন, তারপর আকারের কাজটা টুলের হাতে ছেড়ে দিন৤ টুলে মাপের নিয়ন্ত্রণ থাকলে সেটা 600 বাই 600 করুন আর ফরম্যাট JPG রাখুন৤ ডাউনলোডের পর ফলাফলের মাপ দেখে নিন, কারণ পোর্টাল আকার আর মাপ আলাদাভাবে যাচাই করে৤"},{"question":"50KB করার আগে HEIC-কে JPG-তে বদলাতে হবে?","answer":"না, HEIC ফাইল সরাসরি আপলোড করা যায়৤ টুল আইফোনের HEIC ছবি পড়ে আর কমপ্রেসের সময়ই কনভার্ট করে৤ অন্য অ্যাপে আগে কনভার্ট করার চেয়ে অরিজিনাল HEIC আপলোড করলে ভালো ফল পাওয়া যায়৤"},{"question":"49KB ফাইলও পোর্টাল নিচ্ছে না কেন?","answer":"বাতিলের বার্তাটা ভালো করে পড়ুন৤ সমস্যা প্রায়ই ফরম্যাট বা মাপে, আকারে নয়৤ পোর্টাল JPG বা WebP নেয় কি না নিশ্চিত করুন, প্রয়োজনীয় পিক্সেলের মাপ দেখুন, আর ডিভাইসে দেখানো গোল করা সংখ্যার বদলে ফাইলের আকার বাইটে আবার দেখুন৤"}];
